<?php require __DIR__.'/bootstrap.php';$n=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$err='';$ok=false;if($_SERVER['REQUEST_METHOD']==='POST'){check_token();if($n){$err='التثبيت مغلق: يوجد مستخدم مسجل بالفعل.';}else{try{$pdo->beginTransaction();$w=trim($_POST['workspace']??'');$b=trim($_POST['branch']??'');$name=trim($_POST['name']??'');$user=trim($_POST['username']??'');$pass=$_POST['password']??'';if(!$w||!$b||!$name||strlen($user)<3||strlen($pass)<10)throw new Exception('أكمل الحقول واجعل كلمة المرور 10 أحرف على الأقل.');$q=$pdo->prepare('INSERT INTO workspaces(name,slug) VALUES(?,?)');$q->execute([$w,'ws-'.bin2hex(random_bytes(5))]);$wid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO branches(workspace_id,name,code,is_default) VALUES(?,?,?,1)');$q->execute([$wid,$b,'MAIN']);$bid=(int)$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO users(workspace_id,branch_id,name,username,password_hash,role) VALUES(?,?,?,?,?,'owner')");$q->execute([$wid,$bid,$name,$user,password_hash($pass,PASSWORD_DEFAULT)]);$pdo->commit();$ok=true;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}}
?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/app.css"><title>تثبيت النظام</title><body class="center"><section class="card narrow"><h1>تهيئة ALREDFANI RETAIL ERP</h1><?php if($ok):?><div class="alert good">تم إنشاء مساحة العمل والفرع وحساب المالك. احذف install.php الآن.</div><a class="btn" href="index.php?p=login">تسجيل الدخول</a><?php elseif($n):?><div class="alert">النظام مهيأ بالفعل. احذف ملف install.php.</div><a href="index.php?p=login">الدخول</a><?php else:?><?php if($err):?><div class="alert bad"><?=h($err)?></div><?php endif;?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><label>اسم المنشأة<input name="workspace" required></label><label>الفرع الرئيسي<input name="branch" value="الفرع الرئيسي" required></label><label>اسم المالك<input name="name" required></label><label>اسم المستخدم<input name="username" required minlength="3"></label><label>كلمة المرور<input type="password" name="password" required minlength="10"></label><button class="btn">إنشاء النظام</button></form><?php endif;?></section></body></html>